// E-ink reading index — record JAH-GPC-EINKDISPLAY-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"size_in": 13, "dpi": 200, "price_usd": 700};
var value = (m.size_in*m.dpi/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-EINKDISPLAY-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-EINKDISPLAY-000001|' + value.toFixed(2) + ' reading index');

